import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const l="data:image/png;base64,",p="data:image/png;base64,",i="/assets/zh-cn_image_0000001475211729.Cx4bmUZp.png",r="/assets/zh-cn_image_0000001425411698.D5xAPUSt.png",g=JSON.parse('{"title":"LeakyRelu","description":"","frontmatter":{},"headers":[{"level":1,"title":"LeakyRelu","slug":"leakyrelu"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/基础算术/LeakyRelu.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/基础算术/LeakyRelu.md"}'),o={name:"api/SIMD-API/基础API/Memory矢量计算/基础算术/LeakyRelu.md"};function d(c,a,h,m,k,A){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="leakyrelu" tabindex="-1">LeakyRelu <a class="header-anchor" href="#leakyrelu" aria-label="Permalink to &quot;LeakyRelu&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按元素执行Leaky ReLU（Leaky Rectified Linear Unit）操作，计算公式如下：</p><p><img src="'+l+'" alt=""></p><p>Leaky ReLU带泄露线性整流函数是一种人工神经网络中常用的激活函数，其数学表达式为：</p><p><img src="'+p+'" alt=""></p><p>和ReLU的区别是：ReLU是将所有的负值都设为零，而Leaky ReLU是给所有负值赋予一个斜率。下图表示了Relu和Leaky ReLU的区别：</p><p><img src="'+i+'" alt=""> <img src="'+r+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LeakyRelu(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const T&amp; scalarValue, const int32_t&amp; count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LeakyRelu(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const T&amp; scalarValue, uint64_t mask[], const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LeakyRelu(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const T&amp; scalarValue, uint64_t mask, const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li></ul></li></ul><p>dst和src使用<a href="./../../../基础数据结构/TensorTrait/TensorTrait.html">TensorTrait</a>类型时，其数据类型TensorTrait和scalarValue的数据类型（对应TensorTrait中的LiteType类型）不一致。因此新增模板类型U表示scalarValue的数据类型，并通过std::enable_if检查T中萃取出的LiteType和U是否完全一致，一致则接口通过编译，否则编译失败。接口原型定义如下:</p><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;T&gt;, U&gt;::value, bool&gt;::type = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LeakyRelu(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const U&amp; scalarValue, const int32_t&amp; count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;T&gt;, U&gt;::value, bool&gt;::type = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LeakyRelu(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const U&amp; scalarValue, uint64_t mask[], const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;T&gt;, U&gt;::value, bool&gt;::type = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LeakyRelu(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const U&amp; scalarValue, uint64_t mask, const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Atlas 推理系列产品AI Core，支持的数据类型为：half、float。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half、float。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half、float。 Atlas 200I/500 A2 推理产品，支持的数据类型为：half、float。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half、float。 Kirin X90，支持的数据类型为：half、float。 Kirin 9030，支持的数据类型为：half、float。</td></tr><tr><td>U</td><td>scalarValue数据类型。 Atlas 推理系列产品AI Core，支持的数据类型为：half、float。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half、float。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half、float。 Atlas 200I/500 A2 推理产品，支持的数据类型为：half、float。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half、float。 Kirin X90，支持的数据类型为：half、float。 Kirin 9030，支持的数据类型为：half、float。</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask模式和mask值。 true，表示在接口内部设置。 tensor高维切分计算API/tensor前n个数据计算API内部使用了mask的Normal模式/Counter模式，一般情况下保持isSetMask默认值即可，表示在API内部根据开发者传入的mask/count参数进行mask模式和mask值的设置。 false，表示在接口外部设置。针对tensor高维切分计算接口，对性能要求较高的部分场景下，开发者需要使用SetMaskNorm/SetMaskCount设置mask模式，并通过SetVectorMask接口设置mask值。接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。针对tensor前n个数据计算接口，对性能要求较高的部分场景下，开发者需要使用SetMaskCount设置mask模式为Counter模式，并通过SetVectorMask接口设置mask值。本接口入参中的count不生效，建议设置成1。 针对以下型号，tensor前n个数据计算API中的isSetMask参数不生效，保持默认值即可。 针对Ascend 950PR/Ascend 950DTAtlas 200I/500 A2 推理产品</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>scalarValue</td><td>输入</td><td>源操作数，数据类型需要与目的操作数Tensor中的元素保持一致。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数。 矢量计算单元，每次读取连续的256Bytes数据进行计算，为完成对输入数据的处理，必须通过多次迭代（repeat）才能完成所有数据的读取与计算。repeatTime表示迭代的次数。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>repeatParams</td><td>输入</td><td>元素操作控制结构信息，具体请参考UnaryRepeatParams。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>操作数地址重叠约束请参考<a href="./../../../通用说明和约束.html#section668772811100">通用地址重叠约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>更多样例可参考<a href="./更多样例-9.html">LINK</a>。</p><ul><li><p>tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放LeakyRelu计算结果的输入Tensor</span></span>
<span class="line"><span>// srcLocal: 存放LeakyRelu计算的输入Tensor</span></span>
<span class="line"><span>// scalar: 负斜率系数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uint64_t mask = 128;</span></span>
<span class="line"><span>half scalar = 0.001;</span></span>
<span class="line"><span>// repeatTime = 4, 单次迭代处理128个数，计算512个数需要迭代4次</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, 每个迭代内src0参与计算的数据地址间隔为1个datablock，表示单次迭代内数据连续读取和写入</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, 相邻迭代间的地址间隔为8个datablock，表示相邻迭代间数据连续读取和写入</span></span>
<span class="line"><span>AscendC::LeakyRelu(dstLocal, srcLocal, scalar, mask, 4, {1, 1, 8, 8});</span></span></code></pre></div></li><li><p>tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX };</span></span>
<span class="line"><span>half scalar = 0.001;</span></span>
<span class="line"><span>// repeatTime = 4, 单次迭代处理128个数，计算512个数需要迭代4次</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, 每个迭代内src0参与计算的数据地址间隔为1个datablock，表示单次迭代内数据连续读取和写入</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, 相邻迭代间的地址间隔为8个datablock，表示相邻迭代间数据连续读取和写入</span></span>
<span class="line"><span>AscendC::LeakyRelu(dstLocal, srcLocal, scalar, mask, 4, {1, 1, 8, 8});</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>half scalar = 0.001;</span></span>
<span class="line"><span>// 算子输入的数据类型为half, 需要参与计算的元素个数为512</span></span>
<span class="line"><span>AscendC::LeakyRelu(dstLocal, srcLocal, scalar, 512);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据src0Local：[-287.  246. -438.  177. 596. -950.  -293.  322. ... -900.]</span></span>
<span class="line"><span>输入数据scalar = 0.001</span></span>
<span class="line"><span>输出数据dstLocal：[-0.287 246. -0.438 177. 596. -0.950 -0.293 322. ... -0.900]</span></span></code></pre></div>`,28)])])}const b=t(o,[["render",d]]);export{g as __pageData,b as default};
